+const GRID_COLUMNS = 8;
+const ROW_HEIGHT = 76;
+const GAP = 14;
+const STORAGE_KEY = 'viz-widgets-dashboard/v1';
+
+const WIDGET_META: Record<WidgetType, { title: string; label: string; width: number; height: number }> = {
+  metric: { title: 'Активные сессии', label: 'Метрика', width: 2, height: 2 },
+  chart: { title: 'Трафик по дням', label: 'График', width: 4, height: 3 },
+  status: { title: 'Прогресс релиза', label: 'Статусы', width: 3, height: 2 },
+  tasks: { title: 'Задачи', label: 'Список', width: 2, height: 2 },
+};
+
+const INITIAL_WIDGETS: Widget[] = [
+  { id: 'metric', type: 'metric', x: 0, y: 0, width: 2, height: 2 },
+  { id: 'chart', type: 'chart', x: 2, y: 0, width: 4, height: 3 },
+  { id: 'status', type: 'status', x: 0, y: 2, width: 3, height: 2 },
+  { id: 'tasks', type: 'tasks', x: 6, y: 0, width: 2, height: 2 },
+];
+
+function clamp(value: number, minimum: number, maximum: number) {
+  return Math.min(maximum, Math.max(minimum, value));
+}
+
+function isPositionOccupied(widgets: Widget[], widget: Widget, ignoreId?: string) {
+  return widgets.some((item) => {
+    if (item.id === ignoreId) return false;
+    return (
+      widget.x < item.x + item.width &&
+      widget.x + widget.width > item.x &&
+      widget.y < item.y + item.height &&
+      widget.y + widget.height > item.y
+    );
+  });
+}
+
+function placeWidget(widgets: Widget[], candidate: Widget): Widget {
+  const rows = Math.max(...widgets.map((widget) => widget.y + widget.height), 0);
+  let x = 0;
+  let y = 0;
+
+  while (y <= rows) {
+    const current = { ...candidate, x, y };
+    if ("'!isPositionOccupied(widgets, current, candidate.id)) return current;
+    x += 1;
+    if (x + candidate.width > GRID_COLUMNS) {
+      x = 0;
+      y += 1;
+    }
+  }
+
+  return { ...candidate, x: 0, y: rows };
+}
+
+function packWidgets(widgets: Widget[]): Widget[] {
+  return widgets.reduce<Widget[]>((packed, widget) => [...packed, placeWidget(packed, widget)], []);
+}
+
+function loadWidgets(): Widget[] {
+  if (typeof window === '"'undefined') return INITIAL_WIDGETS;
+
+  try {
+    const raw = window.localStorage.getItem(STORAGE_KEY);
+    if ("'!raw) return INITIAL_WIDGETS;
+    const saved = JSON.parse(raw) as Widget[];
+    if (!Array.isArray(saved)) return INITIAL_WIDGETS;
