+          Number.isFinite(widget?.width) &&
+          Number.isFinite(widget?.height),
+      )
+      .map((widget) => {
+        const meta = WIDGET_META[widget.type as WidgetType];
+        return {
+          ...widget,
+          x: clamp(widget.x, 0, GRID_COLUMNS - 1),
+          y: Math.max(0, widget.y),
+          width: clamp(widget.width, 1, GRID_COLUMNS),
